const NL = String.fromCharCode(10);
const body = $input.first().json.body || $input.first().json;
const event = body.event || 'system.update';
const rawTs = body.timestamp || new Date().toISOString();
const data = body.data || body;

const partnerMap = {
  jackson: 'Jackson Almeida',
  yassin: 'Yassin Khamlichi',
  n8n: 'n8n Automatización'
};

function prettyPartner(val) {
  if (!val) return '';
  const clean = String(val).trim();
  return partnerMap[clean.toLowerCase()] || clean;
}

function formatMadridTime(isoStr) {
  try {
    const d = new Date(isoStr);
    return new Intl.DateTimeFormat('es-ES', {
      timeZone: 'Europe/Madrid',
      day: '2-digit',
      month: 'short',
      hour: '2-digit',
      minute: '2-digit'
    }).format(d).replace(',', ' ·');
  } catch (e) {
    return isoStr;
  }
}

const fechaHora = formatMadridTime(rawTs);
const actor = prettyPartner(data.actor || data.closedBy || 'Omega OS');
let lines = [];

if (event === 'margin.alert') {
  lines = [
    '⚠️ *Alerta financiera · Margen Bruto < 80%*',
    '',
    `📉 Margen actual: *${data.grossMarginPercent}%*`,
    `• MRR activo: ${data.mrr} €/mes`,
    `• Ingresos únicos: ${data.oneOff} €`,
    `• Gastos variables: ${data.variableExpenses} €`,
    '',
    `_Omega OS · ${fechaHora}_`
  ];
} else if (event === 'client.closed' && data.client) {
  const c = data.client;
  lines = [
    '🎉 *¡Nuevo cliente cerrado!* · _Omega Libera_',
    '',
    `*${c.companyName}* (${c.cif})`,
    `• Empleados: ${c.employees}`,
    `• Cuota mensual: *${c.monthlyQuotaEur} €/mes* (MRR)`,
    `• Setup inicial: *${c.setupFeeEur} €*`,
    '',
    `_Cerrado por ${actor} · ${fechaHora}_`
  ];
} else if (data.headline && data.title) {
  const icon = data.icon || '🔔';
  const mod = data.module || 'Omega OS';
  const bullets = Array.isArray(data.bullets) ? data.bullets : [];

  lines.push(`${icon} *${data.headline}* · _${mod}_`);
  lines.push('');
  lines.push(`*${data.title}*`);
  for (const b of bullets) {
    lines.push(`• ${b}`);
  }
  lines.push('');
  lines.push(`_Por ${actor} · ${fechaHora}_`);
} else {
  // Compatibilidad limpia incluso con payloads anteriores de la API
  const p = data.payload || {};
  const mod = data.module || 'Omega OS';
  const rawSummary = String(data.summary || '').replace(/^(Creado|Actualizado|Eliminado):\s*/i, '');
  const actionVerb = data.action === 'POST' ? 'Nuevo registro' : (data.action === 'DELETE' ? 'Eliminado' : 'Actualizado');

  const iconMap = {
    'Tareas': '📋',
    'Notas y Wiki': '📝',
    'Proyectos': '🚀',
    'CRM — Clientes': '🎉',
    'CRM — Leads': '🎯',
    'CRM — Entrevistas': '🎙️',
    'Contactos': '📇',
    'Contabilidad': '💶'
  };
  const icon = iconMap[mod] || '🔔';
  const prioIcons = { Urgente: '🔴 Urgente', Alta: '🟠 Alta', Media: '🔵 Media', Baja: '⚪ Baja' };

  lines.push(`${icon} *${actionVerb}* · _${mod}_`);
  lines.push('');
  lines.push(`*${p.title || p.name || p.companyName || p.company || p.businessName || p.concept || rawSummary}*`);

  if (p.column) lines.push(`• Estado: *${p.column}*`);
  if (p.priority) lines.push(`• Prioridad: ${prioIcons[p.priority] || p.priority}`);
  if (p.assignee) lines.push(`• Responsable: ${prettyPartner(p.assignee)}`);
  if (p.dueDate) lines.push(`• Fecha límite: ${p.dueDate}`);
  if (p.client) lines.push(`• Cliente: ${p.client}`);
  if (p.division) lines.push(`• División: ${p.division}`);
  if (p.type) lines.push(`• Tipo: ${p.type}`);
  if (p.stage) lines.push(`• Etapa: *${p.stage}*`);
  if (p.amountEur !== undefined) lines.push(`• Importe: *${p.amountEur} €*`);

  lines.push('');
  lines.push(`_Por ${actor} · ${fechaHora}_`);
}

const whatsappMessage = lines.join(NL);

return [
  {
    json: {
      event,
      module: data.module || 'Omega OS',
      actor,
      whatsappMessage
    }
  }
];
